def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in me if a == 'D')

    # Short warm-up: cooperate to establish mutual cooperation.
    if n < 3:
        return 'C'

    # Count consecutive opponent defections at the tail.
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            consec_d += 1
        else:
            break

    # Sustained defector: never reward with cooperation.
    if opp_def == n:
        return 'D'

    # Mostly-defecting opponent long-run: defect hard.
    if n >= 8 and opp_def * 10 >= n * 7:
        return 'D'

    # Very cooperative opponent early on: exploit selectively, but never
    # destroy cooperation because mutual CC=3 beats DD=1.
    if opp_def == 0:
        if n >= 20 and my_def == 0:
            # Rare, bounded probes. Keep them infrequent enough that TFT and
            # forgiving opponents do not enter long punishment phases.
            if n % 13 == 0 and rng.random() < 0.5:
                return 'D'
            if n >= 90:
                return 'D'
        return 'C'

    # If we defected last and opponent still cooperated, exploit once more only
    # late, otherwise return to C to preserve cooperation.
    if me[-1] == 'D' and opp[-1] == 'C':
        if n >= 90:
            return 'D'
        return 'C'

    # Opponent just defected.
    if opp[-1] == 'D':
        # Isolated defection by a mostly-cooperative opponent: retaliate once,
        # then forgive quickly to avoid death spiral.
        if opp_def <= 2 and n >= 4:
            if consec_d >= 2:
                # Two in a row: probably a real defector phase; retaliate.
                if rng.random() < 0.15:
                    return 'C'
                return 'D'
            return 'D'

        # Mostly cooperative overall but current streak length 1.
        if opp_def * 4 <= n and consec_d == 1:
            return 'D'

        # Moderate opponents: tit-for-tat retaliation with small forgiveness.
        if consec_d >= 3:
            # Long streak: punish, but probe occasionally to recover.
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # Punish a recent defector briefly if the opponent is not very cooperative.
    if n >= 2 and opp[-2] == 'D' and opp_def * 4 > n:
        if rng.random() < 0.4:
            return 'D'
    return 'C'
